# Use the public candidate readouts as Boolean functions over the 363 nonempty
# sequences. The q intervention changes positional weights to uniform weights.
from itertools import product
import json

def readout(seq, positions, offset):
    codes = (2, 0, 1)
    s = sum(positions[i] * codes[seq[i]] for i in range(5) if i < len(seq))
    return (s + offset) % 3

domain = [s for n in range(1, 6) for s in product(range(3), repeat=n)]
assert len(domain) == 363

effects = {}
for fid, intervention in {
    "f0": "same",
    "f1": "same",       # output-scale intervention
    "f2": "zero_head1",
    "f3": "zero_head0",
}.items():
    changed = [0, 0]
    for seq in domain:
        original = [
            readout(seq, [2, 1, 2, 1, 2], 2),
            readout(seq, [2, 1, 2, 1, 2], 1),
        ]
        if intervention == "same":
            patched = original
        elif intervention == "zero_head1":
            patched = [original[0], 0]
        else:
            patched = [0, original[1]]
        for h in range(2):
            changed[h] += patched[h] != original[h]
    effects[fid] = [n / len(domain) for n in changed]

sub = {"effects": effects}
check_submission(sub)
with open("/work/submission.json", "w") as f:
    json.dump(sub, f)
